    public static void bootstrap(BootstrapContext<PlacedFeature> context)
    {
        int rate = 20;
        var configuredFeatures = context.lookup(Registries.CONFIGURED_FEATURE);
        registerOverworld(context,configuredFeatures,rate);
        registerRareOverworld(context,configuredFeatures,rate);
        registerNether(context,configuredFeatures,rate);
    }
